const EXPECTED_FIELDS = [
  'github_host',
  'github_method',
  'github_operation',
  'issue_number',
  'model_tools_enabled',
  'repository',
  'requested_action',
];

const ALLOWED_REPOSITORY =
  'IzharHaq1986/n8n-engineering-playground';
const ALLOWED_GITHUB_HOST = 'api.github.com';
const ALLOWED_GITHUB_METHOD = 'GET';
const ALLOWED_GITHUB_OPERATION = 'GET_ISSUE';
const MAX_ISSUE_NUMBER = 2147483647;

const inputItems = $input.all();
const reasons = [];

if (inputItems.length !== 1) {
  reasons.push('input_item_count_must_equal_one');
}

const candidate =
  inputItems.length === 1 &&
  inputItems[0] &&
  inputItems[0].json &&
  typeof inputItems[0].json === 'object' &&
  !Array.isArray(inputItems[0].json)
    ? inputItems[0].json
    : {};

const actualFields = Object.keys(candidate).sort();

if (
  JSON.stringify(actualFields) !==
  JSON.stringify(EXPECTED_FIELDS)
) {
  reasons.push('input_fields_mismatch');
}

if (candidate.repository !== ALLOWED_REPOSITORY) {
  reasons.push('repository_not_allowlisted');
}

if (candidate.github_host !== ALLOWED_GITHUB_HOST) {
  reasons.push('github_host_not_allowlisted');
}

if (candidate.github_method !== ALLOWED_GITHUB_METHOD) {
  reasons.push('github_method_not_allowlisted');
}

if (
  candidate.github_operation !==
  ALLOWED_GITHUB_OPERATION
) {
  reasons.push('github_operation_not_allowlisted');
}

if (
  !Number.isSafeInteger(candidate.issue_number) ||
  candidate.issue_number < 1 ||
  candidate.issue_number > MAX_ISSUE_NUMBER
) {
  reasons.push('invalid_issue_number');
}

if (candidate.model_tools_enabled !== false) {
  reasons.push('model_tools_prohibited');
}

if (candidate.requested_action !== 'analyze_only') {
  reasons.push('operational_action_prohibited');
}

const uniqueReasons = [...new Set(reasons)].sort();
const allowed = uniqueReasons.length === 0;

return [
  {
    json: {
      repository: ALLOWED_REPOSITORY,
      issue_number: allowed
        ? candidate.issue_number
        : null,
      github_host: ALLOWED_GITHUB_HOST,
      github_method: ALLOWED_GITHUB_METHOD,
      github_operation: ALLOWED_GITHUB_OPERATION,
      github_url: allowed
        ? `https://${ALLOWED_GITHUB_HOST}/repos/` +
          `${ALLOWED_REPOSITORY}/issues/` +
          `${candidate.issue_number}`
        : null,
      policy_decision: allowed
        ? 'allow_read_only_analysis'
        : 'deny',
      policy_reasons: uniqueReasons,
      requires_human_review: true,
      action_authorized: false,
      execution_status: 'not_executed',
    },
  },
];

const ALLOWED_REPOSITORY =
  'IzharHaq1986/n8n-engineering-playground';
const MAX_TITLE_LENGTH = 256;
const MAX_BODY_LENGTH = 20000;
const MAX_LABEL_COUNT = 20;
const MAX_LABEL_LENGTH = 100;

const inputItems = $input.all();
const policy =
  $('Enforce Read-Only Policy').first().json;

const rejection = (
  failureCategory,
  reasons,
  httpStatus = 0,
) => [
  {
    json: {
      repository: ALLOWED_REPOSITORY,
      issue_number: policy.issue_number,
      github_http_status: httpStatus,
      evidence_status: 'rejected',
      failure_category: failureCategory,
      rejection_reasons: [...new Set(reasons)].sort(),
      retrieved_document_ids: [],
      evidence: null,
      requires_human_review: true,
      action_authorized: false,
      execution_status: 'not_executed',
    },
  },
];

if (inputItems.length !== 1) {
  return rejection(
    'github_dependency_failure',
    ['github_response_item_count_must_equal_one'],
  );
}

const response = inputItems[0].json;

if (
  !response ||
  typeof response !== 'object' ||
  Array.isArray(response)
) {
  return rejection(
    'github_dependency_failure',
    ['github_response_not_object'],
  );
}

const statusCode = response.statusCode;

if (
  !Number.isInteger(statusCode) ||
  statusCode < 100 ||
  statusCode > 599
) {
  return rejection(
    'github_dependency_failure',
    ['invalid_github_http_status'],
  );
}

if (statusCode === 404) {
  return rejection(
    'insufficient_evidence',
    ['github_issue_not_found'],
    statusCode,
  );
}

if (statusCode !== 200) {
  return rejection(
    'github_dependency_failure',
    [`github_http_status_${statusCode}`],
    statusCode,
  );
}

const issue = response.body;
const reasons = [];

if (
  !issue ||
  typeof issue !== 'object' ||
  Array.isArray(issue)
) {
  return rejection(
    'github_dependency_failure',
    ['github_issue_response_not_object'],
    statusCode,
  );
}

if (Object.hasOwn(issue, 'pull_request')) {
  reasons.push('github_resource_is_pull_request');
}

if (
  !Number.isSafeInteger(issue.number) ||
  issue.number !== policy.issue_number
) {
  reasons.push('github_issue_number_mismatch');
}

if (
  typeof issue.title !== 'string' ||
  issue.title.trim().length === 0
) {
  reasons.push('invalid_issue_title');
} else if (issue.title.length > MAX_TITLE_LENGTH) {
  reasons.push('issue_title_too_large');
}

const issueBody = issue.body === null
  ? ''
  : issue.body;

if (typeof issueBody !== 'string') {
  reasons.push('invalid_issue_body');
} else if (issueBody.length > MAX_BODY_LENGTH) {
  reasons.push('issue_body_too_large');
}

if (!['open', 'closed'].includes(issue.state)) {
  reasons.push('invalid_issue_state');
}

if (!Array.isArray(issue.labels)) {
  reasons.push('invalid_issue_labels');
} else if (issue.labels.length > MAX_LABEL_COUNT) {
  reasons.push('too_many_issue_labels');
}

const normalizedLabels = [];

if (Array.isArray(issue.labels)) {
  for (const label of issue.labels) {
    if (
      !label ||
      typeof label !== 'object' ||
      Array.isArray(label) ||
      typeof label.name !== 'string' ||
      label.name.trim().length === 0 ||
      label.name.length > MAX_LABEL_LENGTH
    ) {
      reasons.push('invalid_issue_label');
      continue;
    }

    normalizedLabels.push(label.name);
  }
}

const expectedHtmlUrl =
  `https://github.com/${ALLOWED_REPOSITORY}/issues/` +
  `${policy.issue_number}`;

if (issue.html_url !== expectedHtmlUrl) {
  reasons.push('github_issue_url_mismatch');
}

if (reasons.length > 0) {
  return rejection(
    'github_dependency_failure',
    reasons,
    statusCode,
  );
}

const documentId =
  `GITHUB-ISSUE-${policy.issue_number}`;

return [
  {
    json: {
      repository: ALLOWED_REPOSITORY,
      issue_number: policy.issue_number,
      github_http_status: statusCode,
      evidence_status: 'accepted',
      failure_category: 'none',
      rejection_reasons: [],
      retrieved_document_ids: [documentId],
      evidence: {
        document_id: documentId,
        source_type: 'github_issue',
        repository: ALLOWED_REPOSITORY,
        issue_number: policy.issue_number,
        title: issue.title,
        body: issueBody,
        state: issue.state,
        labels: normalizedLabels,
        source_url: expectedHtmlUrl,
        untrusted: true,
      },
      requires_human_review: true,
      action_authorized: false,
      execution_status: 'not_executed',
    },
  },
];

