const EXPECTED_FIELDS = [
  'action_authorized',
  'evidence_citations',
  'execution_status',
  'recommendation_status',
  'recommended_next_step',
  'requires_human_review',
  'risk_level',
  'summary',
];

const ALLOWED_STATUSES = [
  'grounded',
  'insufficient_evidence',
];

const ALLOWED_RISK_LEVELS = [
  'high',
  'low',
  'medium',
  'unknown',
];

const MAX_SUMMARY_LENGTH = 2000;
const MAX_NEXT_STEP_LENGTH = 1000;
const MAX_CITATIONS = 10;

const executionClaimPattern =
  /\b(?:i|we|agent|system|workflow)\s+(?:have\s+|has\s+)?(?:completed|executed|performed|applied|merged|closed|modified|updated|deleted|created|deployed|rolled\s+back)\b/i;

const normalized =
  $('Normalize GitHub Evidence').first().json;

const retrievedDocumentIds =
  Array.isArray(normalized.retrieved_document_ids)
    ? normalized.retrieved_document_ids
    : [];

const fallback = (
  reasons,
  failureCategory,
) => [
  {
    json: {
      validation_status: 'rejected',
      trusted: false,
      rejection_reasons:
        [...new Set(reasons)].sort(),
      recommendation_status:
        'insufficient_evidence',
      summary:
        'Unable to produce a trusted recommendation.',
      risk_level: 'unknown',
      recommended_next_step:
        'A human reviewer must inspect the recorded failure and approved evidence.',
      evidence_citations: [],
      retrieved_document_ids:
        retrievedDocumentIds,
      github_http_status:
        normalized.github_http_status ?? 0,
      failure_category: failureCategory,
      requires_human_review: true,
      action_authorized: false,
      execution_status: 'not_executed',
    },
  },
];

const inputItems = $input.all();

if (inputItems.length !== 1) {
  return fallback(
    ['openai_response_item_count_must_equal_one'],
    'model_dependency_failure',
  );
}

const response = inputItems[0].json;

if (
  !response ||
  typeof response !== 'object' ||
  Array.isArray(response)
) {
  return fallback(
    ['openai_response_not_object'],
    'model_dependency_failure',
  );
}

if (response.statusCode !== 200) {
  return fallback(
    [`openai_http_status_${response.statusCode ?? 0}`],
    'model_dependency_failure',
  );
}

const responseBody = response.body;

if (
  !responseBody ||
  typeof responseBody !== 'object' ||
  Array.isArray(responseBody)
) {
  return fallback(
    ['openai_response_body_not_object'],
    'model_dependency_failure',
  );
}

if (responseBody.status !== 'completed') {
  return fallback(
    ['openai_response_not_completed'],
    'model_dependency_failure',
  );
}

if (!Array.isArray(responseBody.output)) {
  return fallback(
    ['openai_output_not_array'],
    'invalid_model_output',
  );
}

const outputTexts = [];

for (const outputItem of responseBody.output) {
  if (
    !outputItem ||
    typeof outputItem !== 'object' ||
    outputItem.type !== 'message' ||
    outputItem.role !== 'assistant' ||
    !Array.isArray(outputItem.content)
  ) {
    continue;
  }

  for (const contentItem of outputItem.content) {
    if (
      contentItem &&
      typeof contentItem === 'object' &&
      contentItem.type === 'output_text' &&
      typeof contentItem.text === 'string'
    ) {
      outputTexts.push(contentItem.text);
    }
  }
}

if (outputTexts.length !== 1) {
  return fallback(
    ['structured_output_text_count_must_equal_one'],
    'invalid_model_output',
  );
}

let recommendation;

try {
  recommendation = JSON.parse(outputTexts[0]);
} catch {
  return fallback(
    ['structured_output_invalid_json'],
    'invalid_model_output',
  );
}

if (
  !recommendation ||
  typeof recommendation !== 'object' ||
  Array.isArray(recommendation)
) {
  return fallback(
    ['structured_output_not_object'],
    'invalid_model_output',
  );
}

const reasons = [];
const actualFields =
  Object.keys(recommendation).sort();

if (
  JSON.stringify(actualFields) !==
  JSON.stringify(EXPECTED_FIELDS)
) {
  reasons.push('response_fields_mismatch');
}

if (
  !ALLOWED_STATUSES.includes(
    recommendation.recommendation_status,
  )
) {
  reasons.push('invalid_recommendation_status');
}

if (
  typeof recommendation.summary !== 'string' ||
  recommendation.summary.trim().length === 0 ||
  recommendation.summary.length > MAX_SUMMARY_LENGTH
) {
  reasons.push('invalid_summary');
}

if (
  !ALLOWED_RISK_LEVELS.includes(
    recommendation.risk_level,
  )
) {
  reasons.push('invalid_risk_level');
}

if (
  typeof recommendation.recommended_next_step !==
    'string' ||
  recommendation.recommended_next_step.trim().length ===
    0 ||
  recommendation.recommended_next_step.length >
    MAX_NEXT_STEP_LENGTH
) {
  reasons.push('invalid_recommended_next_step');
}

let citations = recommendation.evidence_citations;

if (!Array.isArray(citations)) {
  reasons.push('citations_not_array');
  citations = [];
} else {
  if (citations.length > MAX_CITATIONS) {
    reasons.push('too_many_citations');
  }

  if (
    citations.some(
      (citation) =>
        typeof citation !== 'string' ||
        citation.length === 0,
    )
  ) {
    reasons.push('invalid_citation');
  }

  if (citations.length !== new Set(citations).size) {
    reasons.push('duplicate_citation');
  }
}

const retrievedSet =
  new Set(retrievedDocumentIds);

if (
  citations.some(
    (citation) => !retrievedSet.has(citation),
  )
) {
  reasons.push('citation_not_retrieved');
}

if (
  recommendation.recommendation_status ===
    'grounded' &&
  citations.length === 0
) {
  reasons.push('grounded_response_without_citation');
}

if (
  recommendation.recommendation_status ===
  'insufficient_evidence'
) {
  if (citations.length !== 0) {
    reasons.push(
      'insufficient_evidence_response_has_citations',
    );
  }

  if (recommendation.risk_level !== 'unknown') {
    reasons.push(
      'insufficient_evidence_risk_must_be_unknown',
    );
  }
}

if (
  recommendation.requires_human_review !== true
) {
  reasons.push('human_review_not_required');
}

if (recommendation.action_authorized !== false) {
  reasons.push('action_authority_not_denied');
}

if (
  recommendation.execution_status !==
  'not_executed'
) {
  reasons.push('invalid_execution_status');
}

const recommendationText = [
  recommendation.summary,
  recommendation.recommended_next_step,
]
  .filter((value) => typeof value === 'string')
  .join(' ');

if (executionClaimPattern.test(recommendationText)) {
  reasons.push('unsupported_execution_claim');
}

if (reasons.length > 0) {
  return fallback(
    reasons,
    'invalid_model_output',
  );
}

return [
  {
    json: {
      validation_status: 'accepted',
      trusted: true,
      rejection_reasons: [],
      recommendation_status:
        recommendation.recommendation_status,
      summary: recommendation.summary,
      risk_level: recommendation.risk_level,
      recommended_next_step:
        recommendation.recommended_next_step,
      evidence_citations: citations,
      retrieved_document_ids:
        retrievedDocumentIds,
      github_http_status:
        normalized.github_http_status,
      failure_category:
        recommendation.recommendation_status ===
        'insufficient_evidence'
          ? 'insufficient_evidence'
          : 'none',
      requires_human_review: true,
      action_authorized: false,
      execution_status: 'not_executed',
    },
  },
];

const WORKFLOW_NAME =
  'Phase 6 - Read-Only GitHub Issue Reliability Advisor';
const MODEL_ID = 'gpt-5.6-luna';

function sha256(text) {
  const bytes = [];

  for (const character of text) {
    const codePoint = character.codePointAt(0);

    if (codePoint <= 0x7f) {
      bytes.push(codePoint);
    } else if (codePoint <= 0x7ff) {
      bytes.push(
        0xc0 | (codePoint >>> 6),
        0x80 | (codePoint & 0x3f),
      );
    } else if (codePoint <= 0xffff) {
      bytes.push(
        0xe0 | (codePoint >>> 12),
        0x80 | ((codePoint >>> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (codePoint >>> 18),
        0x80 | ((codePoint >>> 12) & 0x3f),
        0x80 | ((codePoint >>> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    }
  }

  const bitLength = bytes.length * 8;
  const paddedLength =
    Math.ceil((bytes.length + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);

  padded.set(bytes);
  padded[bytes.length] = 0x80;

  const view = new DataView(padded.buffer);

  view.setUint32(
    paddedLength - 8,
    Math.floor(bitLength / 0x100000000),
    false,
  );

  view.setUint32(
    paddedLength - 4,
    bitLength >>> 0,
    false,
  );

  const rotateRight = (value, shift) =>
    (
      (value >>> shift) |
      (value << (32 - shift))
    ) >>> 0;

  const constants = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf,
    0xe9b5dba5, 0x3956c25b, 0x59f111f1,
    0x923f82a4, 0xab1c5ed5, 0xd807aa98,
    0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7,
    0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
    0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8,
    0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85,
    0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e,
    0x92722c85, 0xa2bfe8a1, 0xa81a664b,
    0xc24b8b70, 0xc76c51a3, 0xd192e819,
    0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c,
    0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee,
    0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7,
    0xc67178f2,
  ];

  const state = [
    0x6a09e667,
    0xbb67ae85,
    0x3c6ef372,
    0xa54ff53a,
    0x510e527f,
    0x9b05688c,
    0x1f83d9ab,
    0x5be0cd19,
  ];

  const words = new Uint32Array(64);

  for (
    let offset = 0;
    offset < paddedLength;
    offset += 64
  ) {
    for (let index = 0; index < 16; index++) {
      words[index] = view.getUint32(
        offset + (index * 4),
        false,
      );
    }

    for (let index = 16; index < 64; index++) {
      const first = words[index - 15];
      const second = words[index - 2];

      const sigma0 = (
        rotateRight(first, 7) ^
        rotateRight(first, 18) ^
        (first >>> 3)
      ) >>> 0;

      const sigma1 = (
        rotateRight(second, 17) ^
        rotateRight(second, 19) ^
        (second >>> 10)
      ) >>> 0;

      words[index] = (
        words[index - 16] +
        sigma0 +
        words[index - 7] +
        sigma1
      ) >>> 0;
    }

    let [
      a,
      b,
      c,
      d,
      e,
      f,
      g,
      h,
    ] = state;

    for (let index = 0; index < 64; index++) {
      const choice = (
        (e & f) ^
        (~e & g)
      ) >>> 0;

      const majority = (
        (a & b) ^
        (a & c) ^
        (b & c)
      ) >>> 0;

      const sum0 = (
        rotateRight(a, 2) ^
        rotateRight(a, 13) ^
        rotateRight(a, 22)
      ) >>> 0;

      const sum1 = (
        rotateRight(e, 6) ^
        rotateRight(e, 11) ^
        rotateRight(e, 25)
      ) >>> 0;

      const temporary1 = (
        h +
        sum1 +
        choice +
        constants[index] +
        words[index]
      ) >>> 0;

      const temporary2 = (
        sum0 +
        majority
      ) >>> 0;

      h = g;
      g = f;
      f = e;
      e = (d + temporary1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temporary1 + temporary2) >>> 0;
    }

    state[0] = (state[0] + a) >>> 0;
    state[1] = (state[1] + b) >>> 0;
    state[2] = (state[2] + c) >>> 0;
    state[3] = (state[3] + d) >>> 0;
    state[4] = (state[4] + e) >>> 0;
    state[5] = (state[5] + f) >>> 0;
