    for (let index = 16; index < 64; index += 1) {
      const word15 = words[index - 15];
      const word2 = words[index - 2];

      const sigma0 =
        rightRotate(word15, 7) ^
        rightRotate(word15, 18) ^
        (word15 >>> 3);

      const sigma1 =
        rightRotate(word2, 17) ^
        rightRotate(word2, 19) ^
        (word2 >>> 10);

      words[index] = (
        words[index - 16] +
        sigma0 +
        words[index - 7] +
        sigma1
      ) >>> 0;
